```ts
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";
import { createPropertyAnimationClip, createPropertyAnimationGroup } from "@babylonjs/lite";

export function fadeIn(manager: AnimationManager, panel: { alpha: number }, durationMs: number): AnimationGroup {
    const durationSec = durationMs / 1000;

    const clip = createPropertyAnimationClip("fadeIn", [
        {
            path: "alpha",
            keys: [
                { time: 0, value: 0 },
                { time: durationSec, value: 1 },
            ],
            interpolation: "linear",
        },
    ]);

    return createPropertyAnimationGroup(manager, panel, clip, { loop: false });
}
```

I created `src/fade-in.ts` which builds a two-key linear property-clip on `panel.alpha` (0 → 1 over `durationMs / 1000` seconds) and returns the non-looping group that `createPropertyAnimationGroup` attaches to the manager and starts playing; once it reaches its end it writes 1, sets `isPlaying` to false, and stops writing. I was not sure of anything — the API and notes cover every behaviour the function relies on.

